const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
let W,H,DPR;function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const world={w:2300,h:1500};const player={x:1150,y:920,r:15,vx:0,vy:0,hp:100,maxHp:100,xp:0,level:1,coins:0,gems:0,face:1,atk:0,dash:0,inv:0,walking:0};
const keys={};addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='j')attack();if(e.key.toLowerCase()==='k')dash();if(e.key.toLowerCase()==='e')talk()});addEventListener('keyup',e=>keys[e.key.toLowerColor?e.key.toLowerColor():e.key.toLowerCase()]=false);
let questKills=0,dialogue=null,toastTimer=0,shake=0;
const elder={x:1050,y:775,r:18};
const slimes=[];for(let i=0;i<10;i++)slimes.push({x:560+(i%5)*260,y:620+(i%2)*470,r:18,hp:3,maxHp:3,flash:0,hit:0,phase:i*1.7});
const trees=[];for(let i=0;i<48;i++){let x=(i*317%world.w),y=(i*193%world.h);if(Math.abs(x-1150)<180&&Math.abs(y-920)<180){x=(x+500)%world.w}trees.push({x,y,s:22+(i*7%18),shade:i%3})}
const rocks=[];for(let i=0;i<35;i++)rocks.push({x:(i*227+180)%world.w,y:(i*379+130)%world.h,s:8+(i%5)*3});
function toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1800)}
function talk(){if(Math.hypot(player.x-elder.x,player.y-elder.y)<90&&questKills<5)openDialogue("Elder Rowan","The moon moths are restless, and the slime swarm grows. Thin their numbers—five should be enough.");else if(Math.hypot(player.x-elder.x,player.y-elder.y)<90&&questKills>=5)openDialogue("Elder Rowan","Well fought, little knight. The forest has remembered its song.");}
function openDialogue(speaker,text){dialogue={};document.getElementById('speaker').textContent=speaker;document.getElementById('dialogueText').textContent=text;document.getElementById('dialogue').classList.remove('hidden')}
document.getElementById('dialogueNext').onclick=()=>document.getElementById('dialogue').classList.add('hidden');
function attack(){if(player.atk>0||dialogue)return;player.atk=.28;shake=3}
function dash(){if(player.dash>0||dialogue)return;player.dash=.38;player.inv=.55;let mx=keys.a||keys.arrowleft?-1:keys.d||keys.arrowright?1:0,my=keys.w||keys.arrowup?-1:keys.s||keys.arrowdown?1:0;if(!mx&&!my)mx=player.face;player.vx=mx*620;player.vy=my*620}
const stick=document.getElementById('stick'),knob=document.getElementById('knob');let joy=false,jx=0,jy=0;
function joyMove(e){let r=stick.getBoundingRect();let p=e.touches?e.touches[0]:e;let cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=p.clientX-cx,dy=p.clientY-cy,l=Math.hypot(dx,dy),m=r.width*.34;if(l>m){dx=dx/l*m;dy=dy/l*m}jx=dx/m;jy=dy/m;knob.style.transform=`translate(${dx}px,${dy}px)`}
stick.addEventListener('pointerdown',e=>{joy=true;stick.setPointerCapture(e.pointerId);joyMove(e)});stick.addEventListener('pointermove',e=>{if(joy)joyMove(e)});stick.addEventListener('pointerup',()=>{joy=false;jx=jy=0;knob.style.transform=''});
document.getElementById('attack').addEventListener('pointerdown',e=>{e.preventPreventDefault?.();attack()});document.getElementById('dash').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
function collide(o){return o.x<35||o.x>world.w-35||o.y<35||o.y>world.h-35}
let particles=[],floaters=[];
function update(dt){if(dialogue)dt*=0;let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+jx,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+jy,l=Math.hypot(mx,my);if(l>1){mx/=l;my/=l}if(player.dash<=0){let sp=220;player.vx=mx*sp;player.vy=my*sp;if(mx)player.face=mx<0?-1:1}else player.dash-=dt;player.atk=Math.max(0,player.atk-dt);player.inv=Math.max(0,player.inv-dt);player.walking=player.walking*0.8+(l>.1?.2:0);player.x+=player.vx*dt;player.y+=player.vy*dt;if(collide(player))player.x-=player.vx*dt,player.y-=player.vy*dt;
for(let s of slimes){if(s.hp<=0)continue;s.flash=Math.max(0,s.flash-dt);s.hit=Math.max(0,s.hit-dt);let dx=player.x-s.x,dy=player.y-s.y,d=Math.hypot(dx,dy);if(d<330&&d>45){s.x+=dx/d*44*dt;s.y+=dy/d*44*dt}s.phase+=dt*2;if(d<32&&player.inv<=0){player.hp-=10;player.inv=1;shake=7;floaters.push({x:player.x,y:player.y-25,text:'-10',life:1,color:'#e78967'});if(player.hp<=0){player.hp=player.maxHp;player.x=1150;player.y=920;toast('The forest releases you')}}
if(player.atk>0&&d<65){if(s.hit<=0){s.hit=.35;s.hp--;shake=4;floaters.push({x:s.x,y:s.y-25,text:'-1',life:.8,color:'#fff1a6'});for(let i=0;i<5;i++)particles.push({x:s.x,y:s.y,vx:(Math.random()-5)*100,vy:(Math.random()-5)*100,life:.5,color:'#b1a965'});if(s.hp<=0){questKills=Math.min(5,questKills+1);player.coins+=8;player.xp+=20;player.gems+=questKills===5?1:0;document.getElementById('coins').textContent=player.coins;document.getElementById('gems').textContent=player.gems;document.getElementById('questCount').textContent=questKills+' / 5';toast(questKills===5?'Quest complete':'Slime defeated');if(player.xp>=100){player.xp-=100;player.level++;player.maxHp+=10;player.hp=player.maxHp;document.getElementById('level').textContent=player.level;toast('Level up!')}}}}}
for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);for(let f of floaters)f.y-=35*dt,f.life-=dt;floaters=floaters.filter(f=>f.life>0);document.getElementById('hpBar').style.width=(player.hp/player.maxHp*100)+'%';document.getElementById('hpText').textContent=Math.ceil(player.hp)+' / '+player.maxHp;document.getElementById('xpBar').style.width=(player.xp/100*100)+'%';shake*=.8}
function drawGround(){ctx.fillStyle='#7f9b61';ctx.fillRect(0,0,W,H);ctx.fillStyle='#718c58';for(let x=-((camera.x)%80)-80;x<W;x+=80)for(let y=-((camera.y)%80)-80;y<H;y+=80){if((Math.floor((x+camera.x)/80)+Math.floor((y+camera.y)/80))%3===0)ctx.fillRect(x,y,80,80)}ctx.fillStyle='rgba(217,205,151,.12)';for(let x=-((camera.x*0.7)%220)-220;x<W;x+=220)ctx.fillRect(x,0,70,H);}
function ellipse(x,y,rx,ry,color){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()}
function sx(x){return x-camera.x}s=sx;
function drawStick(x,y,face,flash){ctx.save();ctx.translate(x,y);ctx.scale(face,1);let walk=Math.sin(performance.now*.012)*4*(player.walking||0);ctx.lineCap='round';ctx.strokeStyle=flash?'#f5df8d':'#202a24';ctx.lineWidth=5;if(player.inv>0&&Math.floor(player.inv*12)%2)ctx.globalAlpha=.55;ellipse(0,-23,10,12,flash?'#f0de9a':'#252e27');ctx.fillStyle='#253a2d';ctx.fillRect(-7,-31,14,7);ctx.strokeStyle=flash?'#f5df8d':'#202a24';ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(0,10);ctx.moveTo(0,-7);ctx.lineTo(-13,-2);ctx.moveTo(0,-7);ctx.lineTo(14,0);ctx.moveTo(0,10);ctx.lineTo(-9,22+walk);ctx.moveTo(0,10);ctx.lineTo(9,22-walk);ctx.stroke();ctx.strokeStyle='#aebd7c';ctx.beginPath();ctx.moveTo(14,0);ctx.lineTo(25,-10);ctx.stroke();ctx.restore();}
function drawTree(t){let x=s(t.x),y=s(t.y);ellipse(x,y+12,t.s*.75,8,'rgba(34,49,31,.28)');ctx.fillStyle='#5a4833';ctx.fillRect(x-4,y-18,8,32);ctx.fillStyle=t.shade?'#435d39':'#526d43';ellipse(x,y-25,t.s,t.s*.8,ctx.fillStyle);ellipse(x-t.s*.55,y-17,t.s*.55,t.s*.5,ctx.fillStyle);ellipse(x+t.s*.55,y-17,t.s*.55,t.s*.5,ctx.fillStyle);ctx.fillStyle='#668052';ellipse(x,y-35,t.s*.7,t.s*.55,ctx.fillStyle)}
const camera={x:0,y:0};
function draw(){let tx=player.x-W/2,ty=player.y-H/2;camera.x+=((Math.max(0,Math.min(world.w-W,tx))-camera.x)*.09);camera.y+=((Math.max(0,Math.min(world.h-H,ty))-camera.y)*.09);ctx.save();let sh=shake?((Math.random()-1)*shake):0;ctx.translate(sh,sh);drawGround();ctx.fillStyle='#536f55';ctx.beginPath();ctx.moveTo(s(820),0);ctx.lineTo(s(1500),0);ctx.lineTo(s(1500),s(520));ctx.lineTo(s(820),s(520));ctx.fill();ellipse(s(elder.x),s(elder.y+12),30,10,'rgba(37,49,34,.35)');ctx.fillStyle='#9e9675';ctx.beginPath();ctx.moveTo(s(elder.x),s(elder.y-30));ctx.lineTo(s(elder.x-14),s(elder.y+12));ctx.lineTo(s(elder.x+14),s(elder.y+12));ctx.fill();ctx.fillStyle='#d8d0a7';ellipse(s(elder.x),s(elder.y-34),7,9,ctx.fillStyle);ctx.strokeStyle='#ddd6ab';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s(elder.x-5),s(elder.y-27));ctx.lineTo(s(elder.x-11),s(elder.y-3));ctx.stroke();
let objs=trees.map(t=>({kind:'tree',y:t.y,v:t}));objs.push({kind:'slime',y:0,v:null});for(let s of slimes)objs.push({kind:'slime',y:s.y,v:s});objs.push({kind:'player',y:player.y,v:player});objs.sort((a,b)=>a.y-b.y);for(let o of objs){if(o.kind==='tree')drawTree(o.v);if(o.kind==='slime'){let q=o.v;if(q.hp<=0)continue;let x=s(q.x),y=s(q.y);ellipse(x,y+10,q.r*.9,5,'rgba(35,52,34,.32)');ctx.save();ctx.translate(x,y+Math.sin(q.phase)*2);ctx.fillStyle=q.flash?'#d7dc86':'#8fae69';ctx.beginPath();ctx.ellipse(0,0,q.r*(1+Math.sin(q.phase)*.06),q.r*.75,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#556e48';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#27342b';ellipse(-6,-4,2.5,3.5,ctx.fillStyle);ellipse(6,-4,2.5,3.5,ctx.fillStyle);ctx.restore();if(q.hp<q.maxHp){ctx.fillStyle='#263323';ctx.fillRect(x-15,y-30,30,4);ctx.fillStyle='#b9bb73';ctx.fillRect(x-15,y-30,30*(q.hp/q.maxHp),4)}}if(o.kind==='player')drawStick(s(o.v.x),s(o.v.y),o.v.face,false)}
for(let r of rocks){let x=s(r.x),y=s(r.y);if(x>-30&&x<W+30&&y>-30&&y<H+30){ellipse(x,y+3,r.s,r.s*.65,'rgba(45,55,41,.3)');ellipse(x,y,r.s,r.s*.65,'#69715e')}}for(let p of particles){ellipse(s(p.x),s(p.y),3,3,p.color)}for(let f of floaters){ctx.fillStyle=f.color;ctx.font='bold 14px Inter';ctx.textAlign='center';ctx.fillText(f.text,s(f.x),s(f.y))}ctx.restore();
requestAnimationFrame(loop)}
let last=performance.now();function loop(now){let dt=Math.min(.033,(now-last)/1000);last=now;update(dt);draw()}requestAnimationFrame(loop);

